// @ai-proposed SAT-0 — generated by the verify-feature skill.
import { test, expect } from '@playwright/test';

async function fill(page, { name, type, description }) {
  await page.goto('/');
  await page.getByLabel('Your name').fill(name);
  await page.getByLabel('Project type').selectOption(type);
  await page.getByLabel('What do you want?').fill(description);
}

test('SAT-0 AC-4 a valid intake shows its reference number', async ({ page }) => {
  await fill(page, { name: 'Ada', type: 'ECOMMERCE', description: 'A storefront for handmade ceramics with a cart' });
  await page.getByRole('button', { name: 'Send intake' }).click();
  await expect(page.getByRole('status')).toHaveText(/Your reference is INT-\d{4,}/);
});

test('SAT-0 AC-5 a short description shows the error and keeps what was typed', async ({ page }) => {
  await fill(page, { name: 'Grace', type: 'API', description: 'too short, 19 chars' });
  await page.getByRole('button', { name: 'Send intake' }).click();
  await expect(page.getByRole('alert')).toHaveText('Describe what you want in at least 20 characters');
  await expect(page.getByLabel('Your name')).toHaveValue('Grace');
  await expect(page.getByLabel('Project type')).toHaveValue('API');
  await expect(page.getByLabel('What do you want?')).toHaveValue('too short, 19 chars');
  await expect(page.getByRole('status')).toHaveCount(0);
});
